#### 文件夾選擇器

- **action**: `folder-selector-modal-open`
- **args 類型**:

  ```typescript
  {
      initialSelectedFolders?: Array<{ id: number; name: string }>;
      // 是否显示“全部素材”
      allMaterials?: boolean;
  }
  ```
- **result.data 類型**:

  ```typescript
  {
      selectedFolders: Array<{ id: number; name: string }>;
      allMaterials: boolean;
  }
  ```
- **示例**:

  ```typescript
  // 请求
  {
      action: "folder-selector-modal-open",
      args: {
          initialSelectedFolders: [{ id: 123, name: '设计素材' }],
          allMaterials: false
      }
  }

  // 成功响应
  {
      result: {
          success: true,
          data: {
              selectedFolders: [
                  { id: 123, name: '设计素材' },
                  { id: 456, name: '产品图片' }
              ],
              allMaterials: false
          }
      }
  }

  // 取消响应
  {
      result: {
          success: false,
          code: "cancelled",
          message: "用户取消操作"
      }
  }
  ```

#### 成員/部門選擇器

- **action**: `member-selector-modal-open`
- **args 類型**:

  ```typescript
  {
      selectedItems?: {
          members?: Array<{ id: string; name: string }>;
          departments?: Array<{ id: string; name: string }>;
          groups?: Array<{ id: string; name: string }>;
      };
  }
  ```
- **result.data 類型**:

  ```typescript
  {
      members: Array<{ id: string; name: string;departmentsName?:string;avatarUrl?:string }>;
      departments: Array<{ id: string; name: string }>;
      groups: Array<{ id: string; name: string }>;
  }
  ```
- **示例**:

  ```typescript
  // 请求
  {
      action: "member-selector-modal-open",
      args: {
          // 已选中项
          selectedItems: {
              members: [{ id: "user_123", name: "张三" ,departmentsName:"Muse, 设计部", avatarUrl:"https://"}],
              departments: [{ id: "dept_001", name: "设计部" }]
          }
      }
  }

  // 成功响应
  {
      result: {
          success: true,
          data: {
              members: [
                  { id: "user_123", name: "张三" },
                  { id: "user_456", name: "李四" }
              ],
              departments: [{ id: "dept_001", name: "设计部" }],
              groups: []
          }
      }
  }

  // 取消响应
  {
      result: {
          success: false,
          code: "cancelled",
          message: "用户取消操作"
      }
  }
  ```

#### 資產選擇器

- **action**: `assets-selector-modal-open`
- **args 類型**:

  ```typescript
  enum EAssetType {
      image = 'image',           // 图片
      video = 'video',           // 视频
      audio = 'audio',           // 音频
      js = 'js',                 // 设计源文件
      document = 'document',     // 文本
      PDocument = 'PDocument',   // 演示文档
      excel = 'excel',           // 表格
      font = 'font',             // 字体
      zip = 'zip',               // 压缩包
      dll = 'dll',               // 应用程序
      code = 'code',             // 代码
      model = 'model',           // 模型
      triD = 'triD',             // 3D
      url = 'url',               // 网页
      unknown = 'unknown',       // 未知文件
  }
  {
    initialSelectedAssetIds?: number[];
    /**
     * 可选择的素材类型。不传则不限制类型。
     * 取值见素材 type 字段，例如：image、video、audio、js、document、PDocument、excel、font、zip、dll、code、model、triD、url
     */
    allowedTypes?: EAssetType[];
    /**
     * 各类型数量限制。传入后仅列出的类型可选；limit 不传表示该类型不限数量。
     * 与 allowedTypes 同时传入时，以 allowedTypes 为白名单，dataLimit 只补充数量上限。
     */
    dataLimit?: Array<{
      type: EAssetType;
      limit?: number;
    }>;
    /**
     * 打开时套用列表筛选（与首页筛选栏一致）。用户仍可在选择器内改筛选。
     */
    filters?: {
      types?: EAssetType[];
      extensions?: string[];
      size?: {
        min?: number;
        max?: number;
        unit?: 'KB' | 'MB' | 'GB';
      };
      dimension?: {
        minWidth?: number;
        maxWidth?: number;
        minHeight?: number;
        maxHeight?: number;
      };
    };
  }
  ```
- **result.data 類型**:

  ```typescript

  {
      selectedAssets: IAssetLite[];
  }
  ```
- **示例**:

  ```typescript
  // 请求
  {
      action: "assets-selector-modal-open",
      args: {
          initialSelectedAssetIds: [123, 456],
          allowedTypes: ['image'],
          filters: {
              types: ['image'],
              size: { min: 100, max: 10240, unit: 'KB' },
              dimension: { minWidth: 512, minHeight: 512 },
          },
      }
  }

  // 成功响应
  {
      result: {
          success: true,
          data: {
              selectedAssets: [
                  { id: 123, name: 'logo.png', type: 'image' },
                  { id: 456, name: 'banner.png', type: 'image' }
              ]
          }
      }
  }

  // 取消响应
  {
      result: {
          success: false,
          code: "cancelled",
          message: "用户取消操作"
      }
  }
  ```

#### 頁面跳轉

- **action**: `goto`
- **args 類型**:

  ```typescript
  {
    url: string;
  }
  ```
- **說明**: 父項目收到此消息後自動執行頁面跳轉，無需響應結果。
- **示例**:

  ```typescript
  // 请求
  {
      action: "goto",
      args: {
          url: "https://example.com/target-page",
          target:"_blank"
      }
  }
  ```

#### 路徑同步

- **action**: `syncPath`
- **args 類型**:

  ```typescript
  {
    path: string;
  }
  ```
- **說明**: 父項目收到此消息後自動更新當前頁面的 hash 路徑，無需響應結果。主要用於同步 iframe 內部的路由狀態到父窗口的 URL。
- **示例**:

  ```typescript
  // 请求
  {
      action: "syncPath",
      args: {
          path: "#path=/tagging/settings"
      }
  }
  ```
